import { CHECKER_SHELL } from './shell.generated';

export const dynamic = 'force-dynamic';
export const runtime = 'nodejs';

/**
 * `/checker` — the M4 checker screen.
 *
 * Serves the generated HTML shell, which loads the mirrored assets from `/checker/*` and posts
 * to `/api/check`. Generated by `src/lib/scam-checker/ui/scripts/sync-public.ts`; do not edit the
 * shell by hand.
 */
export function GET(): Response {
  return new Response(CHECKER_SHELL, {
    status: 200,
    headers: {
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'no-store',
      'x-content-type-options': 'nosniff',
      'referrer-policy': 'no-referrer',
    },
  });
}
